SELECT CASE WHEN price >= 1010 THEN 'high' WHEN price >= 400 THEN 'mid' ELSE 'low' END AS price_bucket, COUNT(CASE WHEN category = 'Electronics' THEN 1 END) AS electronics_count, SUM(CASE WHEN brand = 'Globex' THEN 1 ELSE 0 END) AS globex_count, ROUND((100 * SUM(CASE WHEN category = 'Sports' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_sports FROM products WHERE brand IN ('Stark', 'Globex', 'Acme') GROUP BY CASE WHEN price >= 1010 THEN 'high' WHEN price >= 400 THEN 'mid' ELSE 'low' END
